import React, { useState, useEffect } from 'react';
import api from '../api';

const OrganizerStudio = ({ events, onEventCreated, showToast }) => {
    const [stats, setStats] = useState({ totalRevenue: 0, totalSold: 0, totalCapacity: 192, totalTickets: 0, usedTickets: 0 });
    const [title, setTitle] = useState('');
    const [category, setCategory] = useState('Concerts');
    const [eventDate, setEventDate] = useState('Dec 18, 2026 • 20:00');
    const [venue, setVenue] = useState('');
    const [vipPrice, setVipPrice] = useState(320);
    const [gaPrice, setGaPrice] = useState(140);

    const fetchStats = async () => {
        try {
            const res = await api.get('/organizer/stats');
            setStats(res.data);
        } catch (err) {
            console.error(err);
        }
    };

    useEffect(() => {
        fetchStats();
    }, [events]);

    const handlePublish = async (e) => {
        e.preventDefault();
        try {
            await api.post('/organizer/events', {
                title,
                category,
                eventDate,
                venue,
                vipPrice: Number(vipPrice),
                gaPrice: Number(gaPrice)
            });
            setTitle('');
            setVenue('');
            showToast(`"${title}" is now live in the Catalog.`, 'success');
            onEventCreated();
            fetchStats();
        } catch (err) {
            showToast('Organizer or Admin role required.', 'error');
        }
    };

    const checkinRate = stats.totalTickets > 0 ? Math.round((stats.usedTickets / stats.totalTickets) * 100) : 0;

    return (
        <div className="space-y-6">
            {/* Frosted Apple Health-Style Metric Widgets */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="liquid-glass rounded-[26px] p-5">
                    <p className="text-xs font-medium text-white/55">Gross Revenue</p>
                    <p className="text-2xl font-bold font-mono text-white mt-1">{Number(stats.totalRevenue).toLocaleString()} RON</p>
                    <p className="text-[11px] text-emerald-300 mt-1">● Live Settlement Ledger</p>
                </div>
                <div className="liquid-glass rounded-[26px] p-5">
                    <p className="text-xs font-medium text-white/55">Seats Reserved</p>
                    <p className="text-2xl font-bold font-mono text-white mt-1">{stats.totalSold} / {stats.totalCapacity}</p>
                    <p className="text-[11px] text-white/45 mt-1">Across active venues</p>
                </div>
                <div className="liquid-glass rounded-[26px] p-5">
                    <p className="text-xs font-medium text-white/55">Gate Check-In Rate</p>
                    <p className="text-2xl font-bold font-mono text-white mt-1">{checkinRate}%</p>
                    <p className="text-[11px] text-sky-300 mt-1">{stats.usedTickets} of {stats.totalTickets} scanned</p>
                </div>
                <div className="liquid-glass rounded-[26px] p-5">
                    <p className="text-xs font-medium text-white/55">Automation Savings</p>
                    <p className="text-2xl font-bold font-mono text-white mt-1">4,200 RON</p>
                    <p className="text-[11px] text-white/45 mt-1">Zero-staff optical lanes</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                <div className="lg:col-span-5 liquid-glass rounded-[30px] p-6">
                    <h3 className="text-lg font-bold text-white mb-1">Publish New Event</h3>
                    <p className="text-xs text-white/55 mb-5">Provisions a 48-seat spatial map in MySQL automatically.</p>

                    <form onSubmit={handlePublish} className="space-y-4">
                        <div>
                            <label className="block text-xs font-medium text-white/70 mb-1.5 pl-1">Event Title</label>
                            <input required type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="e.g., Subcarpați Symphonic Live" className="w-full px-4 py-2.5 rounded-2xl liquid-well text-sm text-white placeholder-white/30 focus:outline-none focus:border-white/40" />
                        </div>
                        <div className="grid grid-cols-2 gap-3">
                            <div>
                                <label className="block text-xs font-medium text-white/70 mb-1.5 pl-1">Category</label>
                                <select value={category} onChange={(e) => setCategory(e.target.value)} className="w-full px-3.5 py-2.5 rounded-2xl liquid-well text-sm text-white focus:outline-none">
                                    <option value="Concerts" className="bg-slate-900">Concerts</option>
                                    <option value="Festivals" className="bg-slate-900">Festivals</option>
                                    <option value="Theater" className="bg-slate-900">Theater</option>
                                    <option value="Comedy" className="bg-slate-900">Comedy</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-medium text-white/70 mb-1.5 pl-1">Date &amp; Time</label>
                                <input required type="text" value={eventDate} onChange={(e) => setEventDate(e.target.value)} className="w-full px-3.5 py-2.5 rounded-2xl liquid-well text-sm text-white focus:outline-none" />
                            </div>
                        </div>
                        <div>
                            <label className="block text-xs font-medium text-white/70 mb-1.5 pl-1">Venue</label>
                            <input required type="text" value={venue} onChange={(e) => setVenue(e.target.value)} placeholder="e.g., BTarena, Cluj-Napoca" className="w-full px-4 py-2.5 rounded-2xl liquid-well text-sm text-white placeholder-white/30 focus:outline-none" />
                        </div>
                        <div className="grid grid-cols-2 gap-3">
                            <div>
                                <label className="block text-xs font-medium text-white/70 mb-1.5 pl-1">VIP Price (RON)</label>
                                <input required type="number" min="50" value={vipPrice} onChange={(e) => setVipPrice(e.target.value)} className="w-full px-4 py-2.5 rounded-2xl liquid-well text-sm font-mono text-white focus:outline-none" />
                            </div>
                            <div>
                                <label className="block text-xs font-medium text-white/70 mb-1.5 pl-1">General (RON)</label>
                                <input required type="number" min="20" value={gaPrice} onChange={(e) => setGaPrice(e.target.value)} className="w-full px-4 py-2.5 rounded-2xl liquid-well text-sm font-mono text-white focus:outline-none" />
                            </div>
                        </div>
                        <button type="submit" className="w-full py-3.5 rounded-full glass-pill-btn font-bold text-sm mt-1">
                            Publish to Catalog
                        </button>
                    </form>
                </div>

                <div className="lg:col-span-7 liquid-glass rounded-[30px] p-6 space-y-4">
                    <div className="flex items-center justify-between">
                        <h3 className="text-lg font-bold text-white">Venue Occupancy</h3>
                        <span className="text-xs font-mono text-emerald-300">● Synced</span>
                    </div>
                    <div className="space-y-3.5">
                        {events.map(ev => {
                            const pct = Math.round((ev.soldCount / ev.totalCapacity) * 100);
                            return (
                                <div key={ev.id} className="liquid-well rounded-2xl p-4 space-y-2.5">
                                    <div className="flex flex-wrap items-center justify-between gap-2">
                                        <div>
                                            <h4 className="font-semibold text-white text-sm">{ev.title}</h4>
                                            <p className="text-xs text-white/50">{ev.venue} • {ev.date}</p>
                                        </div>
                                        <span className="font-mono text-xs font-semibold text-white/85">{ev.soldCount} / {ev.totalCapacity} ({pct}%)</span>
                                    </div>
                                    <div className="w-full h-2 bg-white/10 rounded-full overflow-hidden">
                                        <div className="h-full bg-white rounded-full transition-all duration-500" style={{ width: `${pct}%` }}></div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default OrganizerStudio;
